package scan

import (
	"testing"

	"github.com/aquasecurity/fanal/analyzer"
)

func TestAnalyzeLockfilesSeparately(t *testing.T) {
	paths := []string{"/first/Pipfile.lock", "/second/Pipfile.lock"}
	versions := []string{"1.0.0", "2.0.0"}
	for i, path := range paths {
		content := []byte(`{"default":{"example":{"version":"==` + versions[i] + `"}}}`)
		result, err := analyzer.AnalyzeFile(path, &DummyFileInfo{}, func() ([]byte, error) {
			return content, nil
		})
		if err != nil {
			t.Fatalf("analyze %s: %v", path, err)
		}
		scanners := convertLibWithScanner(result)
		if len(scanners) != 1 || scanners[0].Path != path || len(scanners[0].Libs) != 1 ||
			scanners[0].Libs[0].Name != "example" || scanners[0].Libs[0].Version != versions[i] {
			t.Errorf("unexpected scanner for %s: %#v", path, scanners)
		}
	}
}

