package libmanager

import (
	"testing"

	"github.com/future-architect/vuls/models"
)

func TestAppendLibraryVulnInfoKeepsBothLockfiles(t *testing.T) {
	r := &models.ScanResult{ScannedCves: models.VulnInfos{}}
	for _, path := range []string{"/first/Pipfile.lock", "/second/Pipfile.lock"} {
		appendLibraryVulnInfo(r, models.VulnInfo{
			CveID: "CVE-1234-5678",
			LibraryFixedIns: models.LibraryFixedIns{{
				Path: path, Name: "example", FixedIn: "3.0.0",
			}},
		})
	}
	got := r.ScannedCves["CVE-1234-5678"].LibraryFixedIns
	if len(r.ScannedCves) != 1 || len(got) != 2 ||
		got[0].Path != "/first/Pipfile.lock" || got[1].Path != "/second/Pipfile.lock" {
		t.Fatalf("duplicate CVE lost a lockfile: %#v", got)
	}
}
